'use strict';
/**
 * config.js - the app's configuration, which cannot live in app.json "settings".
 *
 * app.json settings are a fixed list of bool / choice / number items rendered by the HMI (see
 * kit/tools/build.py: there is no free-text widget), so a URL, a 180-character long-lived access
 * token and a list of entity tiles cannot be typed in on the car. They live in a JSON file in
 * ctx.dataDir instead:
 *
 *   <dataDir>/ha.json        written over Wi-Fi / scp, or generated by the deploy script
 *
 * Shape (everything but baseUrl and token is optional):
 *   {
 *     "baseUrl": "https://ha.lan:8123",
 *     "token": "eyJ...",                     // long-lived access token
 *     "verifyTls": true,                     // false only for a self-signed certificate
 *     "caFile": "ha-ca.pem",                 // relative to dataDir; better than verifyTls:false
 *     "dashboardEntity": "sensor.car_dashboard",   // optional: HA defines the tiles (see below)
 *     "doorbell": {
 *       "trigger": { "entity": "binary_sensor.front_doorbell", "to": "on" },
 *       "camera": "camera.front_door",
 *       "label": "Front door"
 *     },
 *     "push": { "prefix": "bmw_m3", "webhook": "car_state" },
 *     "pages": [
 *       { "title": "House", "tiles": [
 *         { "entity": "light.porch", "name": "Porch", "tap": "toggle" },
 *         { "entity": "cover.garage", "name": "Garage", "tap": "cover.open_cover" },
 *         { "entity": "scene.leaving", "name": "Leaving", "tap": "scene.turn_on" },
 *         { "entity": "sensor.house_power", "name": "Power", "tap": "none", "unit": "W" }
 *       ] }
 *     ]
 *   }
 *
 * "tap" is 'toggle' (homeassistant.toggle), 'none', or an explicit "domain.service"; the tile's
 * entity_id is passed as the target. A tile with no "tap" gets 'toggle' for the domains that have
 * one and 'none' otherwise.
 *
 * Letting HA own the layout: set "dashboardEntity" to an entity whose attributes carry the same
 * "pages" array (a template sensor is the easy way). Then the tiles are edited in HA and the car
 * picks them up on the next state_changed - no file copying. The file's own "pages" is the
 * fallback for when HA is unreachable, and ha.json is still needed for the URL and token.
 */
const fs = require('fs');
const path = require('path');

const TOGGLEABLE = ['light', 'switch', 'fan', 'input_boolean', 'automation', 'climate', 'media_player', 'humidifier', 'siren'];

const DEFAULTS = {
    baseUrl: '',
    token: '',
    verifyTls: true,
    extraEvents: [],
    pages: [],
    doorbell: null,
    push: { prefix: 'bmw', webhook: '' },
    dashboardEntity: '',
};

/** The default tap action for an entity id. */
function defaultTap(entity) {
    const domain = String(entity || '').split('.')[0];
    if (domain === 'scene') return 'scene.turn_on';
    if (domain === 'script') return 'script.turn_on';
    if (domain === 'cover') return 'cover.toggle';
    if (domain === 'lock') return 'lock.unlock';
    if (domain === 'button' || domain === 'input_button') return domain + '.press';
    return TOGGLEABLE.indexOf(domain) >= 0 ? 'toggle' : 'none';
}

/** One tile, with everything filled in and nothing trusted. */
function cleanTile(t) {
    if (!t || typeof t.entity !== 'string' || t.entity.indexOf('.') < 0) return null;
    return {
        entity: t.entity,
        name: typeof t.name === 'string' && t.name ? t.name : t.entity.split('.')[1].replace(/_/g, ' '),
        tap: typeof t.tap === 'string' && t.tap ? t.tap : defaultTap(t.entity),
        data: t.data && typeof t.data === 'object' ? t.data : null,
        unit: typeof t.unit === 'string' ? t.unit : '',
        confirm: t.confirm === true,
    };
}

/** Pages from any source (file or HA attributes), cleaned; [] when there is nothing usable. */
function cleanPages(pages) {
    if (!Array.isArray(pages)) return [];
    return pages.map((p, i) => ({
        title: p && typeof p.title === 'string' && p.title ? p.title : 'Page ' + (i + 1),
        tiles: ((p && p.tiles) || []).map(cleanTile).filter((t) => t).slice(0, 12),
    })).filter((p) => p.tiles.length).slice(0, 6);
}

/**
 * Read <dataDir>/ha.json. Never throws: a missing or broken file gives the defaults plus an
 * `error` the screen can show, because an app that exits on a typo in a config file is useless.
 */
function load(dataDir, log) {
    const file = path.join(dataDir, 'ha.json');
    const cfg = Object.assign({}, DEFAULTS, { file: file, error: '', ca: null });
    let text = null;
    try { text = fs.readFileSync(file, 'utf8'); } catch (e) {
        cfg.error = 'ha.json not found - copy it to ' + file;
        return cfg;
    }
    let raw = null;
    try { raw = JSON.parse(text); } catch (e) {
        cfg.error = 'ha.json is not valid JSON: ' + e.message;
        return cfg;
    }
    ['baseUrl', 'token', 'dashboardEntity'].forEach((k) => { if (typeof raw[k] === 'string') cfg[k] = raw[k].trim(); });
    if (cfg.baseUrl) cfg.baseUrl = cfg.baseUrl.replace(/\/+$/, '');
    if (raw.verifyTls === false) cfg.verifyTls = false;
    if (Array.isArray(raw.extraEvents)) cfg.extraEvents = raw.extraEvents.filter((s) => typeof s === 'string').slice(0, 8);
    cfg.pages = cleanPages(raw.pages);
    if (raw.push && typeof raw.push === 'object') {
        cfg.push = {
            prefix: typeof raw.push.prefix === 'string' && raw.push.prefix ? raw.push.prefix : 'bmw',
            webhook: typeof raw.push.webhook === 'string' ? raw.push.webhook : '',
        };
    }
    if (raw.doorbell && typeof raw.doorbell === 'object') {
        const d = raw.doorbell;
        const trig = d.trigger && typeof d.trigger === 'object' ? d.trigger : {};
        cfg.doorbell = {
            entity: typeof trig.entity === 'string' ? trig.entity : '',
            to: typeof trig.to === 'string' ? trig.to : 'on',
            camera: typeof d.camera === 'string' ? d.camera : '',
            label: typeof d.label === 'string' && d.label ? d.label : 'Front door',
        };
        if (!cfg.doorbell.entity && !cfg.doorbell.camera) cfg.doorbell = null;
    }
    if (typeof raw.caFile === 'string' && raw.caFile) {
        try { cfg.ca = fs.readFileSync(path.join(dataDir, raw.caFile)); } catch (e) {
            cfg.error = 'caFile could not be read: ' + e.message;
        }
    }
    if (!cfg.baseUrl || !cfg.token) cfg.error = cfg.error || 'ha.json needs both "baseUrl" and "token"';
    if (log) {
        log.info('config: ' + (cfg.error ? 'problem - ' + cfg.error
            : cfg.baseUrl + ', ' + cfg.pages.length + ' page(s)' + (cfg.dashboardEntity ? ', layout from ' + cfg.dashboardEntity : '')));
    }
    return cfg;
}

/** Pages from the HA dashboard entity's attributes, else the ones from the file. */
function pagesFor(cfg, state) {
    if (cfg.dashboardEntity && state && state.attributes) {
        const fromHa = cleanPages(state.attributes.pages);
        if (fromHa.length) return { pages: fromHa, from: 'ha' };
    }
    return { pages: cfg.pages, from: cfg.pages.length ? 'file' : 'none' };
}

module.exports = { load, pagesFor, cleanPages, defaultTap, TOGGLEABLE };
